      {
        "start": 167.07999999999998,
        "end": 167.88,
        "text": "这些功能"
      },
      {
        "start": 167.88,
        "end": 169.24,
        "text": "如果你在其他软件用"
      },
      {
        "start": 169.24,
        "end": 171.24,
        "text": "还得额外付费皆为Di"
      },
      {
        "start": 171.24,
        "end": 173.16,
        "text": "如果你对AI办公室用要求"
      },
      {
        "start": 173.16,
        "end": 174.12,
        "text": "是快速高效"
      },
      {
        "start": 174.12,
        "end": 175.96,
        "text": "现在这个斗包工作的功能"
      },
      {
        "start": 175.96,
        "end": 177.2,
        "text": "已经非常全面了"
      },
      {
        "start": 177.2,
        "end": 179.12,
        "text": "但敬品调研还有一个麻烦"
      },
      {
        "start": 179.12,
        "end": 179.92000000000002,
        "text": "今天查完"
      },
      {
        "start": 179.92000000000002,
        "end": 181.44,
        "text": "并不代表下周还有效"
      },
      {
        "start": 181.44,
        "end": 182.56,
        "text": "芯品 价格"
      },
      {
        "start": 182.56,
        "end": 184.28,
        "text": "行业动态每天都在变"
      },
      {
        "start": 184.28,
        "end": 186.04,
        "text": "下面给这个AZ的团队"
      },
      {
        "start": 186.04,
        "end": 187.16,
        "text": "安排一个定识任务"
      },
      {
        "start": 187.16,
        "end": 189,
        "text": "每天从海量行业资讯中"
      },
      {
        "start": 189,
        "end": 190.4,
        "text": "找到有价值的内容"
      },
      {
        "start": 190.4,
        "end": 192.56,
        "text": "在输入框直接输入这段骑士词"
      },
      {
        "start": 195.28,
        "end": 196.32,
        "text": "这个定识任务"
      },
      {
        "start": 196.32,
        "end": 197.52,
        "text": "就算创养OK了"
      },
      {
        "start": 197.52,
        "end": 199.4,
        "text": "我们来看一下效果吧"
      },
      {
        "start": 199.4,
        "end": 201.12,
        "text": "这个呈现我还挺喜欢的"
      },
      {
        "start": 201.12,
        "end": 202.48,
        "text": "重点非常清楚"
      },
      {
        "start": 202.48,
        "end": 203.76,
        "text": "既不是一大拖文字"
